resource "kubernetes_ingress_v1" "this" {
  count = local.module_config.enable_ingress ? 1 : 0
  metadata {
    name      = "${local.module_config.name}-ingress"
    namespace = kubernetes_namespace.this.metadata[0].name
    annotations = merge({
      "kubernetes.io/ingress.class"                           = "traefik"
      "traefik.ingress.kubernetes.io/router.entrypoints"      = "websecure"
      "traefik.ingress.kubernetes.io/router.tls"              = "true"
      "traefik.ingress.kubernetes.io/router.tls.certresolver" = local.module_config.traefik_cert_resolver
      }, local.module_config.traefik_cert_resolver == "wildcard" ? {
      "traefik.ingress.kubernetes.io/router.tls.domains.0.main" = local.module_config.domain_name
      "traefik.ingress.kubernetes.io/router.tls.domains.0.sans" = "*.${local.module_config.domain_name}"
      } : {
      "traefik.ingress.kubernetes.io/router.tls.domains.0.main" = "loki.${local.module_config.domain_name}"
    })
  }

  spec {
    ingress_class_name = "traefik"
    tls {
      hosts = ["loki.${local.module_config.domain_name}"]
    }
    rule {
      host = "loki.${local.module_config.domain_name}"
      http {
        path {
          path      = "/"
          path_type = "Prefix"
          backend {
            service {
              name = data.kubernetes_service.gateway[0].metadata[0].name
              port {
                number = 80
              }
            }
          }
        }
      }
    }
  }
  depends_on = [helm_release.this]
}

resource "kubernetes_config_map" "palette_installer_script" {
  count = var.enable_persistence && length(var.palette_packages) > 0 ? 1 : 0

  metadata {
    name      = "${var.name}-palette-installer-script"
    namespace = kubernetes_namespace.this.metadata[0].name
    labels    = local.common_labels
  }

  data = {
    "install-palette.sh" = templatefile("${path.module}/templates/install-palette.sh.tpl", {
      palette_packages = var.palette_packages
    })
  }
}

resource "kubernetes_job_v1" "palette_installer" {
  count = var.enable_persistence && length(var.palette_packages) > 0 ? 1 : 0

  wait_for_completion = false

  timeouts {
    create = "2m"
    delete = "5m"
  }

  metadata {
    name      = "${var.name}-palette-installer"
    namespace = kubernetes_namespace.this.metadata[0].name
    labels    = local.common_labels
  }

  spec {
    template {
      metadata {
        labels = local.common_labels
      }
      spec {
        restart_policy = "OnFailure"

        # Node selector for architecture
        node_selector = var.disable_arch_scheduling ? {} : {
          "kubernetes.io/arch" = var.cpu_arch
        }

        container {
          name              = "palette-installer"
          image             = "nodered/node-red:latest"
          image_pull_policy = "IfNotPresent"
          working_dir       = "/data"

          command = ["/bin/sh", "/scripts/install-palette.sh"]

          resources {
            limits = {
              cpu    = "1000m"
              memory = "1Gi"
            }
            requests = {
              cpu    = "500m"
              memory = "512Mi"
            }
          }

          volume_mount {
            name       = "data"
            mount_path = "/data"
          }

          volume_mount {
            name       = "script"
            mount_path = "/scripts"
            read_only  = true
          }
        }

        volume {
          name = "data"
          persistent_volume_claim {
            claim_name = kubernetes_persistent_volume_claim.data_storage[0].metadata[0].name
          }
        }

        volume {
          name = "script"
          config_map {
            name         = kubernetes_config_map.palette_installer_script[0].metadata[0].name
            default_mode = "0755"
          }
        }
      }
    }

    backoff_limit              = 3
    ttl_seconds_after_finished = 300 # Clean up after 5 minutes
  }

  depends_on = [
    helm_release.this,
    kubernetes_persistent_volume_claim.data_storage
  ]
}

