resource "kubernetes_service_account" "this" {
  metadata {
    name      = local.rbac_config.service_account_name
    namespace = kubernetes_namespace.this.metadata[0].name
    labels    = local.common_labels
  }

  depends_on = [kubernetes_namespace.this]
}

resource "kubernetes_cluster_role" "this" {
  metadata {
    name   = local.rbac_config.cluster_role_name
    labels = local.common_labels
  }

  rule {
    api_groups = [""]
    resources  = ["nodes", "nodes/proxy", "services", "endpoints", "pods", "pods/log"]
    verbs      = ["get", "watch", "list"]
  }

  rule {
    api_groups = ["apps"]
    resources  = ["daemonsets", "deployments", "replicasets"]
    verbs      = ["get", "watch", "list"]
  }

  rule {
    api_groups = ["extensions", "networking.k8s.io"]
    resources  = ["ingresses"]
    verbs      = ["get", "watch", "list"]
  }

  rule {
    api_groups = [""]
    resources  = ["namespaces"]
    verbs      = ["get", "watch", "list"]
  }

  rule {
    non_resource_urls = ["/metrics"]
    verbs             = ["get"]
  }
}

resource "kubernetes_cluster_role_binding" "this" {
  metadata {
    name   = local.rbac_config.cluster_role_binding_name
    labels = local.common_labels
  }

  role_ref {
    api_group = "rbac.authorization.k8s.io"
    kind      = "ClusterRole"
    name      = kubernetes_cluster_role.this.metadata[0].name
  }

  subject {
    kind      = "ServiceAccount"
    name      = kubernetes_service_account.this.metadata[0].name
    namespace = kubernetes_namespace.this.metadata[0].name
  }
}

resource "kubernetes_secret" "additional_dns_credentials" {
  for_each = { for idx, provider in try(var.dns_providers.additional, []) : idx => provider }

  metadata {
    name      = "${each.value.name}-dns-credentials"
    namespace = kubernetes_namespace.this.metadata[0].name
  }
  type = "Opaque"
  data = {
    for key, value in each.value.config : replace(lower(key), "_", "-") => value
  }
}

resource "kubernetes_secret" "basic_auth" {
  count = var.basic_auth.enabled ? 1 : 0

  metadata {
    name      = var.basic_auth.secret_name != "" ? var.basic_auth.secret_name : "${var.name_prefix}-basic-auth-secret"
    namespace = var.namespace
    labels    = var.labels
  }

  data = {
    users = "${var.basic_auth.username}:${bcrypt(local.basic_auth_password, 10)}"
  }

  type = "Opaque"
}

resource "kubernetes_secret" "default_auth" {
  count = var.default_auth.enabled && !var.default_auth.ldap_override ? 1 : 0

  metadata {
    name      = var.default_auth.basic_config.secret_name != "" ? var.default_auth.basic_config.secret_name : "${var.name_prefix}-default-auth-secret"
    namespace = var.namespace
    labels    = var.labels
  }

  data = {
    users = "${var.default_auth.basic_config.username}:${bcrypt(local.default_auth_password, 10)}"
  }

  type = "Opaque"
}

resource "kubernetes_secret" "ldap_auth_secret" {
  count = var.ldap_auth.enabled && var.ldap_auth.method == "forwardauth" ? 1 : 0

  metadata {
    name      = "${var.name_prefix}-ldap-auth-secret"
    namespace = var.namespace
    labels    = var.labels
  }

  data = {
    secret_key = base64encode(random_password.ldap_auth_secret_key[0].result)
  }
}

resource "kubernetes_deployment" "ldap_auth_service" {
  count = var.ldap_auth.enabled && var.ldap_auth.method == "forwardauth" ? 1 : 0

  metadata {
    name      = "${var.name_prefix}-ldap-auth-service"
    namespace = var.namespace
    labels    = var.labels
  }

  spec {
    replicas = 1
    selector {
      match_labels = {
        app = "${var.name_prefix}-ldap-auth"
      }
    }
