          env_from {
            secret_ref {
              name = kubernetes_secret.n8n_secret.metadata[0].name
            }
          }

          # Resource limits
          resources {
            limits = {
              cpu    = var.cpu_limit
              memory = var.memory_limit
            }
            requests = {
              cpu    = var.cpu_request
              memory = var.memory_request
            }
          }

          # Health checks
          liveness_probe {
            http_get {
              path = "/healthz"
              port = 5678
